# Generated by `cargo xtask formula` in https://github.com/michel-onstein/acs for each release
# (scripts/update-tap.sh): edit the generator there, not this file.
# acs-version: 0.19.0
#
# acs releases are signed; SHA256SUMS.sig is checked against this key:
#   ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAILbxQW5C9X7CdwcQ4bab0gsQi4Evk2xfgmI/972dlHCb acs release signing
# Verify a release by hand:
#   printf 'releases@acs namespaces="acs-release" %s\n' "$key" > allowed
#   ssh-keygen -Y verify -f allowed -I releases@acs -n acs-release -s SHA256SUMS.sig < SHA256SUMS
class Acs < Formula
  desc "Persistent, reconnecting remote shells over ssh"
  homepage "https://github.com/michel-onstein/acs"
  license "MIT"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/michel-onstein/acs/releases/download/0.19.0/acs-0.19.0-aarch64-apple-darwin.tar.gz"
      sha256 "566b2e99d56c1041d041e4f46c1dfd27ef2d07c902e34675a50f7c89a086edb8"
    end

    on_intel do
      url "https://github.com/michel-onstein/acs/releases/download/0.19.0/acs-0.19.0-x86_64-apple-darwin.tar.gz"
      sha256 "442e0526ed7fbda2621dedc66ee900ad76687729a1431a2b4594848a36c606ce"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/michel-onstein/acs/releases/download/0.19.0/acs-0.19.0-aarch64-unknown-linux-musl.tar.gz"
      sha256 "2ac2407247adacca2e63ec3080fb70ec84cc91b4c2fb76dbb81e69f525881bf7"
    end

    on_intel do
      url "https://github.com/michel-onstein/acs/releases/download/0.19.0/acs-0.19.0-x86_64-unknown-linux-musl.tar.gz"
      sha256 "b89685af063573d4a67f4fbdb70c129b32c9b116a2718c32b1b2d8571b89008a"
    end
  end

  def install
    bin.install "acs"
    bin.install_symlink "acs" => "acscp"
  end

  test do
    out = shell_output("#{bin}/acs --version")
    assert_match "acs #{version} ", out
    remotes = out[/^installs remotes: (.*)$/, 1].to_s.split(", ")
    assert_includes remotes, "x86_64-unknown-linux-musl"
    assert_includes remotes, "aarch64-unknown-linux-musl"
    assert_match "acs #{version} ", shell_output("#{bin}/acscp --version")
  end
end
